import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../../components/Navbar';
import { FaUser, FaEnvelope, FaCalendar, FaTrophy, FaFire, FaClock, FaSignOutAlt } from 'react-icons/fa';

function Profile() {
  const navigate = useNavigate();
  const [user, setUser] = useState({
    name: '',
    email: '',
    joined: ''
  });

  useEffect(() => {
    setUser({
      name: localStorage.getItem('userName') || 'User',
      email: localStorage.getItem('userEmail') || 'user@example.com',
      joined: new Date().toLocaleDateString()
    });
  }, []);

  const stats = [
    { icon: <FaFire color="#e74c3c" />, value: '12', label: 'Day Streak' },
    { icon: <FaTrophy color="#f39c12" />, value: '8', label: 'Badges Earned' },
    { icon: <FaClock color="#3498db" />, value: '245', label: 'Focus Minutes' },
  ];

  const handleLogout = () => {
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userName');
    localStorage.removeItem('userEmail');
    navigate('/');
  };

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>👤 Profile</h1>
          <p style={styles.subtitle}>Manage your account and view your progress</p>
        </div>

        <div style={styles.profileCard}>
          <div style={styles.avatar}>
            <FaUser size={60} color="#667eea" />
          </div>
          <h2 style={styles.userName}>{user.name}</h2>
          <div style={styles.userInfo}>
            <div><FaEnvelope /> {user.email}</div>
            <div><FaCalendar /> Joined {user.joined}</div>
          </div>
        </div>

        <div style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <div key={index} style={styles.statCard}>
              <div style={styles.statIcon}>{stat.icon}</div>
              <div style={styles.statValue}>{stat.value}</div>
              <div style={styles.statLabel}>{stat.label}</div>
            </div>
          ))}
        </div>

        <div style={styles.menuCard}>
          <h3>Settings</h3>
          <button onClick={handleLogout} style={styles.logoutBtn}>
            <FaSignOutAlt /> Logout
          </button>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f5f7fa',
  },
  content: {
    maxWidth: '600px',
    margin: '0 auto',
    padding: '20px',
    paddingTop: '80px',
  },
  header: {
    textAlign: 'center',
    marginBottom: '30px',
  },
  title: {
    fontSize: '32px',
    color: '#333',
  },
  subtitle: {
    color: '#666',
    marginTop: '5px',
  },
  profileCard: {
    background: 'white',
    borderRadius: '20px',
    padding: '30px',
    textAlign: 'center',
    marginBottom: '20px',
  },
  avatar: {
    width: '100px',
    height: '100px',
    background: '#f0f0ff',
    borderRadius: '50%',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    margin: '0 auto 20px',
  },
  userName: {
    fontSize: '24px',
    marginBottom: '10px',
  },
  userInfo: {
    color: '#666',
    fontSize: '14px',
    display: 'flex',
    flexDirection: 'column',
    gap: '5px',
  },
  statsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(3, 1fr)',
    gap: '15px',
    marginBottom: '20px',
  },
  statCard: {
    background: 'white',
    borderRadius: '15px',
    padding: '20px',
    textAlign: 'center',
  },
  statIcon: {
    fontSize: '24px',
    marginBottom: '10px',
  },
  statValue: {
    fontSize: '24px',
    fontWeight: 'bold',
    color: '#333',
  },
  statLabel: {
    fontSize: '12px',
    color: '#666',
  },
  menuCard: {
    background: 'white',
    borderRadius: '20px',
    padding: '20px',
  },
  logoutBtn: {
    width: '100%',
    padding: '12px',
    background: '#e74c3c',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '10px',
    marginTop: '15px',
  },
};

export default Profile;
